test('calcula el total con 18% de impuesto', () => {
  // Arrange
  const carrito = new Carrito();
  carrito.agregarItem({ precio: 100, cantidad: 1 });

  // Act
  const total = carrito.calcularTotalConImpuesto(0.18);

  // Assert
  expect(total).toBe(118);
});

